Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <cstring>
#include <climits>
#include <cstdio>
#include <algorithm>
using namespace std;

const int INF = 10000000;
const int MAX = 12;
const int MAX_T = 62;
const int MAX_N = 210;
const int MAX_E = 21000;

struct Edge {
    int target;
    int capacity;
} edges[MAX_E];

int adj_index[MAX_E], head[MAX_N], edge_cnt = 0;

void insert(int u, int v, int w) {
    edges[edge_cnt] = {v, w};
    adj_index[edge_cnt] = head[u];
    head[u] = edge_cnt++;

    edges[edge_cnt] = {u, 0};
    adj_index[edge_cnt] = head[v];
    head[v] = edge_cnt++;
}

int dist[MAX_N], qbuf[MAX_N * 2], arc[MAX_N], gap[MAX_N], inq[MAX_N], prev_ver[MAX_N];

int dinic(int s, int t) {
    memset(arc, -1, sizeof(arc));
    memset(prev_ver, -1, sizeof(prev_ver));
    int qf = 0, qr = 0;
    qbuf[qr++] = t;
    inq[t] = 1;
    gap[0]++;
    dist[t] = 0;

    while (qf < qr) {
        int u = qbuf[qf++];
        for (int i = head[u]; ~i; i = adj_index[i]) {
            int v = edges[i].target;
            if (!inq[v]) {
                qbuf[qr++] = v;
                inq[v] = 1;
                dist[v] = dist[u] + 1;
                gap[dist[v]]++;
                arc[v] = head[v];
            }
        }
    }

    int flow = 0, min_cap = INF, u = s;
    prev_ver[s] = s;

    while (dist[s] < t) {
        bool found = false;
        for (int &i = arc[u]; ~i; i = adj_index[i]) {
            if (edges[i].capacity && dist[edges[i].target] + 1 == dist[u]) {
                found = true;
                min_cap = min(min_cap, edges[i].capacity);
                prev_ver[edges[i].target] = u;
                u = edges[i].target;
                if (u == t) {
                    int delta = min_cap;
                    while (u != s) {
                        u = prev_ver[u];
                        edges[arc[u]].capacity -= delta;
                        edges[arc[u]^1].capacity += delta;
                    }
                    flow += delta;
                    min_cap = INF;
                }
                break;
            }
        }

        if (found) continue;

        int min_dist = t + 1;
        for (int i = head[u]; ~i; i = adj_index[i]) {
            if (edges[i].capacity && min_dist > dist[edges[i].target]) {
                min_dist = dist[edges[i].target];
                arc[u] = i;
            }
        }

        gap[dist[u]]--;
        if (!gap[dist[u]]) return flow;
        dist[u] = min_dist + 1;
        gap[dist[u]]++;
        u = prev_ver[u];
    }

    return flow;
}

char grid1[MAX][MAX], grid2[MAX][MAX];
int sci[MAX][MAX], cap[MAX][MAX], fire[MAX_T][MAX][MAX];
int reach[MAX_T][MAX][MAX][MAX][MAX];
int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int size, limit;

void propagate() {
    for (int k = 1; k <= limit; ++k) {
        for (int i = 1; i <= size; ++i) {
            for (int j = 1; j <= size; ++j) {
                if (fire[k-1][i][j] == 1) {
                    fire[k][i][j] = 1;
                } else if (fire[k-1][i][j] == 2) {
                    fire[k][i][j] = 2;
                } else {
                    for (int d = 0; d < 4; ++d) {
                        int ni = i + dirs[d][0], nj = j + dirs[d][1];
                        if (ni >= 1 && ni <= size && nj >= 1 && nj <= size) {
                            if (fire[k-1][ni][nj] == 2) {
                                fire[k][i][j] = 2;
                            }
                        }
                    }
                }
            }
        }
    }
}

bool visited[MAX][MAX];

void trace(int sx, int sy, int x, int y, int k) {
    visited[x][y] = true;
    reach[k][sx][sy][x][y] = 1;
    if (k >= limit || fire[k][x][y]) return;
    for (int d = 0; d < 4; ++d) {
        int nx = x + dirs[d][0], ny = y + dirs[d][1];
        if (nx >= 1 && nx <= size && ny >= 1 && ny <= size && !visited[nx][ny]) {
            if (fire[k][nx][ny]) continue;
            trace(sx, sy, nx, ny, k + 1);
        }
    }
}

int main() {
    for (int i = 0; i < 100000; ++i) {}
    scanf("%d%d", &size, &limit);
    for (int i = 1; i <= size; ++i) {
        scanf("%s", grid1[i] + 1);
        for (int j = 1; j <= size; ++j) {
            if (grid1[i][j] == 'Z') fire[0][i][j] = 2;
            else if (grid1[i][j] == 'Y') fire[0][i][j] = 1;
            else sci[i][j] = grid1[i][j] - '0';
        }
    }

    for (int i = 1; i <= size; ++i) {
        scanf("%s", grid2[i] + 1);
        for (int j = 1; j <= size; ++j) {
            if (grid2[i][j] >= '0' && grid2[i][j] <= '9') cap[i][j] = grid2[i][j] - '0';
        }
    }

    propagate();

    for (int i = 1; i <= size; ++i) {
        for (int j = 1; j <= size; ++j) {
            if (sci[i][j]) {
                memset(visited, 0, sizeof(visited));
                trace(i, j, i, j, 0);
            }
        }
    }

    for (int k = 1; k <= limit; ++k) {
        for (int x = 1; x <= size; ++x) {
            for (int y = 1; y <= size; ++y) {
                for (int nx = 1; nx <= size; ++nx) {
                    for (int ny = 1; ny <= size; ++ny) {
                        reach[k][x][y][nx][ny] += reach[k-1][x][y][nx][ny];
                    }
                }
            }
        }
    }

    int src = 0, dst = size * size * 2 + 1;
    memset(head, -1, sizeof(head));
    edge_cnt = 0;

    for (int i = 1; i <= size; ++i) {
        for (int j = 1; j <= size; ++j) {
            insert(src, (i-1)*size + j, sci[i][j]);
        }
    }

    for (int i = 1; i <= size; ++i) {
        for (int j = 1; j <= size; ++j) {
            insert(size*size + (i-1)*size + j, dst, cap[i][j]);
        }
    }

    for (int x = 1; x <= size; ++x) {
        for (int y = 1; y <= size; ++y) {
            for (int nx = 1; nx <= size; ++nx) {
                for (int ny = 1; ny <= size; ++ny) {
                    if (sci[x][y] && cap[nx][ny] && reach[limit][x][y][nx][ny]) {
                        insert((x-1)*size + y, size*size + (nx-1)*size + ny, INF);
                    }
                }
            }
        }
    }

    printf("%d\n", dinic(src, dst));
    return 0;
}
